<?php [$requests,$number,$pages]=pageRows('return_requests','id DESC',($_GET['state']??'')==='all'?'1=1':"status='pending'");pageLinks('admin/returns',$number,$pages);if(!$requests):?><div class="empty"><h2>Gösterilecek iade talebi yok.</h2></div><?php endif;foreach($requests as $r):$order=query('SELECT * FROM orders WHERE id=?',[$r['order_id']])->fetch();?>
