<?php if($r['status']==='pending'):startform('return_decide','form-grid');?><input type="hidden" name="request_id" value="<?=$r['id']?>"><label>Karar<select name="decision" required><option value="">Seçin</option><option value="approved">Onayla</option><option value="rejected">Reddet</option></select></label><label>Müşteriye yanıt / iade yönlendirmesi<textarea name="reply" minlength="5" maxlength="2000" required></textarea></label><button class="button dark">Kararı kaydet</button></form><?php else:?><p><strong>Yanıt:</strong> <?=nl2br(e($r['reply']))?></p><small><?=e($r['decided'])?></small><?php endif?></article><?php endforeach?>
